//! Standalone controller assets (fu67) — the deploy slice baked into the
//! binary so `noo onboard --standalone` works with NO repo checkout.
//!
//! `STANDALONE_ASSETS` is generated by build.rs from the ACTUAL repo files
//! (compose, config templates, the launch-script chain, prompts/skills,
//! monitoring/grafana configs). `materialize()` writes them under a home dir
//! (default `~/.noo`), which onboard then treats as `repo_root` — so the whole
//! existing wizard flow (which funnels through `repo_root.join(...)`) runs
//! unchanged. Secrets, PKI, and the live `noomesh.yaml` are generated at
//! onboard time and are NOT embedded here.
//!
//! Because these assets ride the binary, updating them = updating the binary
//! (`noo upgrade`) — the single self-contained update path (fu66).

include!(concat!(env!("OUT_DIR"), "/standalone_assets.rs"));

use std::io;
use std::path::{Path, PathBuf};

/// Default standalone home: `$NOO_HOME`, else `~/.noo`.
pub fn default_home() -> PathBuf {
    if let Ok(h) = std::env::var("NOO_HOME") {
        let h = h.trim();
        if !h.is_empty() {
            return PathBuf::from(h);
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| ".".into());
    PathBuf::from(home).join(".noo")
}

/// Number of embedded assets (sanity/logging).
pub fn asset_count() -> usize {
    STANDALONE_ASSETS.len()
}

/// Prepare a no-repo controller before the wizard runs: materialise the deploy
/// slice under `home`, point `repo_root()` at it, force dist mode, and noop the
/// dev-only source overlays so the baked image content serves. Idempotent —
/// safe on re-onboard. After this, the existing wizard flow runs unchanged
/// because every step reads/writes under `repo_root()` == `home`.
pub fn prepare(home: &Path) -> io::Result<()> {
    materialize(home)?;
    finish_prepare(home)
}

/// Mode B (fu67): prepare from an EXTERNAL bundle instead of the embedded
/// assets — `noo onboard --standalone --bundle <url|path>`. The bundle is a
/// tar.gz of the same dest-relpaths `noo bundle export` writes, verified
/// against its `.sha256` sidecar, entries validated against path traversal,
/// then the same post-steps as the embedded path. This is the "config
/// unpinned from the CLI version" override; the embedded path stays the
/// default.
pub fn prepare_from_bundle(home: &Path, bundle: &str) -> Result<(), String> {
    let (bytes, sha_line) = acquire_bundle(bundle)?;
    if let Some(expected) = sha_line {
        let expected = expected.split_whitespace().next().unwrap_or("").to_lowercase();
        let got = {
            use sha2::{Digest as _, Sha256};
            let mut h = Sha256::new();
            h.update(&bytes);
            h.finalize().iter().map(|b| format!("{b:02x}")).collect::<String>()
        };
        if expected.is_empty() || expected != got {
            return Err(format!(
                "bundle sha256 mismatch (expected {expected}, got {got}) — refusing"));
        }
    }
    std::fs::create_dir_all(home).map_err(|e| e.to_string())?;
    extract_bundle_safely(&bytes, home)?;
    // Same non-asset seeds as the embedded path.
    std::fs::write(home.join(STANDALONE_MARKER),
        format!("materialized from bundle {bundle} by noo {}\n", env!("CARGO_PKG_VERSION")))
        .map_err(|e| e.to_string())?;
    finish_prepare(home).map_err(|e| e.to_string())
}

/// Fetch the bundle (+ sha sidecar). A local path takes a sibling `.sha256`
/// when present (warns when absent); a URL REQUIRES one — a remote artifact
/// with no checksum is not verifiable. Token env (GH_TOKEN/GITHUB_TOKEN)
/// rides along when set, for a private release mirror.
fn acquire_bundle(bundle: &str) -> Result<(Vec<u8>, Option<String>), String> {
    if bundle.starts_with("http://") {
        return Err("refusing a plaintext http:// bundle URL — use https:// or a local path".into());
    }
    if bundle.starts_with("https://") {
        let tok = crate::commands::upgrade::gh_token();
        let bytes = crate::commands::upgrade::http_get_bytes(bundle, tok.as_deref())?;
        let sha = crate::commands::upgrade::http_get_bytes(
            &format!("{bundle}.sha256"), tok.as_deref())
            .map_err(|e| format!("a URL bundle requires its .sha256 sidecar: {e}"))?;
        return Ok((bytes, Some(String::from_utf8_lossy(&sha).into_owned())));
    }
    let bytes = std::fs::read(bundle).map_err(|e| format!("cannot read bundle {bundle}: {e}"))?;
    let sidecar = format!("{bundle}.sha256");
    let sha = match std::fs::read_to_string(&sidecar) {
        Ok(s) => Some(s),
        Err(_) => {
            println!("{}", crate::ui::sub(&crate::ui::status_line(crate::ui::Glyph::Warn, &format!("no {sidecar} — local bundle accepted unverified"))));
            None
        }
    };
    Ok((bytes, sha))
}

/// Extract with system tar after validating EVERY entry: relative, no `..`,
/// no absolute paths. GNU tar's own defaults vary by version, so this
/// validation is the guarantee, not tar's.
pub(crate) fn extract_bundle_safely(bytes: &[u8], home: &Path) -> Result<(), String> {
    let tmp = std::env::temp_dir().join(format!("noo-bundle-{}.tgz", std::process::id()));
    std::fs::write(&tmp, bytes).map_err(|e| e.to_string())?;
    let done = |r: Result<(), String>| { let _ = std::fs::remove_file(&tmp); r };

    let list = std::process::Command::new("tar").arg("-tzf").arg(&tmp).output()
        .map_err(|e| format!("tar: {e}"))?;
    if !list.status.success() {
        return done(Err("not a valid tar.gz bundle (or, for an encrypted archive, a wrong passphrase)".into()));
    }
    for entry in String::from_utf8_lossy(&list.stdout).lines() {
        let e = entry.trim().trim_end_matches('/');
        if e.is_empty() || e == "." { continue; }
        if e.starts_with('/') || e.split('/').any(|c| c == "..") {
            return done(Err(format!("bundle entry escapes the target dir: {entry}")));
        }
    }
    let ok = std::process::Command::new("tar")
        .arg("-xzf").arg(&tmp).arg("-C").arg(home)
        .status().map(|s| s.success()).unwrap_or(false);
    done(if ok { Ok(()) } else { Err("bundle extraction failed".into()) })
}

/// The post-materialise half of prepare(): env plumbing shared by the
/// embedded (Mode A) and bundle (Mode B) paths.
pub(crate) fn finish_prepare(home: &Path) -> io::Result<()> {
    // An empty dir the dev-only bind overlays can mount harmlessly.
    let noop = home.join(".noop-overlay");
    std::fs::create_dir_all(&noop)?;

    // repo_root() checks $NOO_REPO_ROOT first → the whole wizard operates here.
    std::env::set_var("NOO_REPO_ROOT", home);
    std::env::set_var("NOO_STANDALONE", "1");

    // A no-repo box cannot build images — dist only. Seed the bootstrap flag so
    // the install-mode step resolves to dist without prompting.
    seed_install_mode_dist(home)?;

    // The dist images bake the UI, gateway src, and trellion; the compose file's
    // dev overlays default to `./src...`, which a no-repo box lacks. Point each
    // overlay at the empty dir and its dest at a throwaway path, so the baked
    // content wins instead of being masked by an empty mount.
    let noop_s = noop.to_string_lossy().to_string();
    std::env::set_var("NOO_UI_STATIC_OVERLAY", &noop_s);
    std::env::set_var("NOO_UI_STATIC_OVERLAY_DEST", "/app/.ui-overlay-noop");
    std::env::set_var("NOO_SRC_OVERLAY", &noop_s);
    std::env::set_var("NOO_SRC_OVERLAY_DEST", "/app/.src-noop");
    std::env::set_var("TRELLION_SRC", &noop_s);
    std::env::set_var("TRELLION_SRC_DEST", "/opt/.trellion-noop");
    Ok(())
}

/// Seed `NOO_INSTALL_MODE=dist` + `NOO_DEFAULT_PROFILE=standalone` into
/// `home/.env` if not already set — a no-repo controller can only run released
/// images, and a bare day-2 `noo stack start` must default to the lean profile
/// (the launcher reads NOO_DEFAULT_PROFILE from .env), not the full
/// `controller` one.
fn seed_install_mode_dist(home: &Path) -> io::Result<()> {
    let env = home.join(".env");
    let existing = std::fs::read_to_string(&env).unwrap_or_default();
    // NOO_IMAGE_TAG: the stack release this CLI is PAIRED with, baked at
    // build time — a no-repo box has no `git tag` for the launcher's normal
    // dist-tag resolution. Empty (crate-only build) seeds nothing; onboard
    // then needs the operator to set NOO_IMAGE_TAG in .env.
    let mut seeds: Vec<(&str, &str)> =
        vec![("NOO_INSTALL_MODE", "dist"), ("NOO_DEFAULT_PROFILE", "standalone")];
    if !STANDALONE_STACK_TAG.is_empty() {
        seeds.push(("NOO_IMAGE_TAG", STANDALONE_STACK_TAG));
        seeds.push(("NOO_IMAGE_PREFIX", crate::registry::IMAGE_NAMESPACE));
    }
    // Base images from OUR public ghcr mirrors (mirror-images.yml,
    // multi-arch), not from dhi.io — the ghcr login the wizard already
    // requires then covers EVERY pull, and a fresh box needs no Docker
    // account (first contact hit that wall live). The default seeded here is
    // the DHI runtime family under the `dhi/` prefix (registry.rs
    // PUBLIC_BASE_REGISTRY), the uids every service key and data volume is
    // handed to; NEVER the upstream mirrors at the bare namespace, whose
    // images run as other uids (0.6.1 restart loops). Pinned by a test in
    // registry.rs and tests/test_image_namespace_*.
    seeds.push(("NOO_BASE_REGISTRY", crate::registry::PUBLIC_BASE_REGISTRY));
    let (body, reseeded) = apply_seeds(&existing, &seeds, PAIRING_KEYS, stack_present());
    for key in &reseeded {
        println!("{}", crate::ui::note(&format!(
            "{key} re-seeded to this build's pairing (the value came from an older noo; no stack exists yet)")));
    }
    if body != existing {
        std::fs::write(&env, body)?;
    }
    Ok(())
}

/// Keys whose value is a property of the BINARY, not of the install: the
/// stack tag and namespace this build was released with. Everything else
/// seeded here is set once and left alone.
const PAIRING_KEYS: &[&str] = &["NOO_IMAGE_TAG", "NOO_IMAGE_PREFIX"];

/// Is any stack container on this box? Once one exists the pairing belongs
/// to `noo upgrade --stack` (a signed roll), never to a re-seed.
fn stack_present() -> bool {
    std::process::Command::new("docker")
        .args(["ps", "-aq", "--filter", "name=noo-gateway"])
        .output()
        .map(|o| o.status.success() && !String::from_utf8_lossy(&o.stdout).trim().is_empty())
        .unwrap_or(false)
}

/// Pure half of the seed: absent keys are appended; a PAIRING key that is
/// present with another value is rewritten when no stack exists yet —
/// the 2026-09-07 walk started on noo 0.5.5 (paired v0.2.27), upgraded
/// itself to 0.5.7 (paired v0.2.28) and relaunched, and the relaunch kept
/// the stale tag because "seed only what is absent" cannot tell a
/// pairing from a choice. Returns the new body and the keys re-seeded.
fn apply_seeds(existing: &str, seeds: &[(&str, &str)], pairing: &[&str], stack_present: bool) -> (String, Vec<String>) {
    let mut lines: Vec<String> = existing.lines().map(str::to_string).collect();
    let mut reseeded = Vec::new();
    for (key, val) in seeds {
        let prefix = format!("{key}=");
        match lines.iter().position(|l| l.trim_start().starts_with(&prefix)) {
            None => lines.push(format!("{key}={val}")),
            Some(i) if pairing.contains(key) && !stack_present => {
                let current = lines[i].trim_start()[prefix.len()..].trim();
                if current != *val {
                    lines[i] = format!("{key}={val}");
                    reseeded.push(key.to_string());
                }
            }
            Some(_) => {}
        }
    }
    let mut body = lines.join("\n");
    if !body.is_empty() {
        body.push('\n');
    }
    (body, reseeded)
}

/// Day-2 marker filename — envfile::repo_root() keys off this.
const STANDALONE_MARKER: &str = ".noo-standalone";

/// Manifest of what the last `materialize()` wrote — next to
/// `STANDALONE_MARKER`. Lets the NEXT materialise tell a
/// file this release stopped shipping apart from one this box never had.
const MATERIALISED_MANIFEST: &str = ".noo-materialised";

/// Report handed back by `materialize()` so its callers can print what
/// happened to a file an earlier release shipped and this one does not
/// Empty on a fresh install — nothing to retire yet.
#[derive(Default)]
pub struct MaterializeReport {
    /// "retired <path> (no longer shipped)"
    pub retired: Vec<String>,
    /// "moved aside <path> → <new name> (edited locally; this release no longer ships it)"
    pub moved_aside: Vec<String>,
    /// Anything the retire step could not act on, or noted along the way
    /// (a corrupt manifest, a path that failed the safety check, an IO
    /// error on one path) — never fatal to `materialize()` itself.
    pub skipped: Vec<String>,
}

/// Write the embedded deploy slice under `home`, creating parent dirs and
/// marking scripts executable. Overwrites embedded assets (they track the
/// binary version — "config rides the binary"); it never touches files that
/// are NOT embedded (the live `noomesh.yaml`, `secrets/`, `pki/`), so
/// re-running is safe and refreshes compose/scripts to the current version.
///
/// Also retires files a PAST release embedded that this one does not
/// See `finish_materialize` for the manifest + retire
/// contract. The retire step never fails `materialize` — an upgrade must
/// not abort over a stale file — its notes ride the returned report.
pub fn materialize(home: &Path) -> io::Result<MaterializeReport> {
    write_assets(home)?;
    let report = finish_materialize(
        home, STANDALONE_ASSETS, RENDERED_ONCE, KNOWN_RETIRED, env!("CARGO_PKG_VERSION"));
    // A fresh controller starts with an EMPTY inventory (no nodes yet); the
    // PKI step reads it and issues only CA + gateway/service certs. The live
    // hosts file is deliberately not embedded (it would carry another fleet).
    // Marker for day-2 ops: envfile::repo_root() falls back to a home dir
    // carrying this marker, so `noo stack start` / `noo cluster status` find
    // the standalone install WITHOUT the user exporting NOO_REPO_ROOT.
    std::fs::write(home.join(STANDALONE_MARKER),
        format!("materialized by noo {} — see docs/getting-started/standalone-controller.md\n",
            env!("CARGO_PKG_VERSION")))?;
    Ok(report)
}

/// Write ONLY the embedded assets under `home` — the shared core of
/// materialize() and `noo bundle export`. Refuses on an empty table (binary
/// built outside the repo tree; crate-only CI builds do this legitimately, a
/// RELEASE binary never should — the release workflow greps for the sentinel).
/// Embedded assets that are a SEED, not a template: the wizard renders
/// them for this install and a later materialise must not put the seed
/// back. `users.conf` is the per-principal NATS user table —
/// `noo upgrade --stack` re-materialised the slice on 2026-09-07 and the
/// one-user seed replaced the rendered file, so the v0.2.28 gateway (which
/// presents its own `gateway` principal) was refused by its own bus and
/// crash-looped until the file was re-rendered.
const RENDERED_ONCE: &[&str] = &["monitoring/nats/users.conf"];

pub(crate) fn write_assets(home: &Path) -> io::Result<()> {
    if STANDALONE_ASSETS.is_empty() {
        return Err(io::Error::other(
            "this noo binary carries no embedded standalone assets (built \
             outside the repo tree) — install a released binary (noo upgrade / \
             install.sh) or run onboard from a checkout"));
    }
    for (rel, bytes, exec) in STANDALONE_ASSETS {
        let dest = home.join(rel);
        if let Some(parent) = dest.parent() {
            std::fs::create_dir_all(parent)?;
        }
        if RENDERED_ONCE.contains(rel) && dest.is_file() {
            // Install-specific once written; the embedded copy is only the
            // seed for a box that has none yet.
            continue;
        }
        std::fs::write(&dest, bytes)?;
        #[cfg(unix)]
        if *exec {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(0o755))?;
        }
    }
    Ok(())
}

