    #[test]
    fn materialize_round_trips() {
        if STANDALONE_ASSETS.is_empty() {
            eprintln!("crate-only build (no repo tree) — round-trip skipped");
            return;
        }
        let tmp = std::env::temp_dir().join(format!("noo-standalone-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);
        materialize(&tmp).expect("materialize");

        // A representative file wrote with real bytes.
        let compose = tmp.join("docker-compose.cluster.yml");
        assert!(compose.is_file());
        assert!(std::fs::metadata(&compose).unwrap().len() > 1000);

        // Scripts are executable.
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(tmp.join("scripts/noomesh-start.sh"))
                .unwrap().permissions().mode();
            assert!(mode & 0o111 != 0, "launch script not executable: {mode:o}");
        }

        // No ansible inventory. The playbook tree went in 3695e129 and every
        // verb that read this file is gone, so writing one on a fresh
        // controller created a file nothing reads — and left the next reader
        // believing the fleet had no nodes rather than that the concept had
        // been retired.
        assert!(
            !tmp.join("ansible").exists(),
            "standalone onboard must not create an ansible tree"
        );

        // Day-2 marker: envfile::repo_root() keys off this file.
        assert!(tmp.join(".noo-standalone").is_file(), "missing day-2 marker");

        // Day-2 defaults seeded (dist + lean profile), and idempotent.
        seed_install_mode_dist(&tmp).unwrap();
        seed_install_mode_dist(&tmp).unwrap();
        let env = std::fs::read_to_string(tmp.join(".env")).unwrap();
        assert_eq!(env.matches("NOO_INSTALL_MODE=dist").count(), 1);
        assert_eq!(env.matches("NOO_DEFAULT_PROFILE=standalone").count(), 1);

        let _ = std::fs::remove_dir_all(&tmp);
    }

    /// Finding #28 (third of its class after #21/#22): a launcher script
    /// grew a `source lib-*.sh` line whose lib was never embedded, and the
    /// standalone launch died at that line. This test derives the
    /// requirement instead of trusting the hand-maintained manifest: every
    /// lib-*.sh referenced by ANY embedded scripts/*.sh must be embedded.
    #[test]
    fn embedded_launchers_have_their_libs() {
        if STANDALONE_ASSETS.is_empty() {
            eprintln!("crate-only build (no repo tree) — lib check skipped");
            return;
        }
        let embedded: std::collections::HashSet<&str> =
            STANDALONE_ASSETS.iter().map(|(d, _, _)| *d).collect();
        for (dest, bytes, _) in STANDALONE_ASSETS {
            if !dest.starts_with("scripts/") || !dest.ends_with(".sh") {
                continue;
            }
            let body = String::from_utf8_lossy(bytes);
            for line in body.lines() {
                let t = line.trim();
                if t.starts_with('#') {
                    continue;
                }
                let Some(pos) = t.find("lib-") else { continue };
                // only source/dot lines, not prose in comments/strings
                if !(t.starts_with("source ") || t.starts_with(". ")) {
                    continue;
                }
                let Some(end) = t[pos..].find(".sh") else { continue };
                let lib = format!("scripts/{}", &t[pos..pos + end + 3]);
                assert!(
                    embedded.contains(lib.as_str()),
                    "{dest} sources {lib}, which is NOT in STANDALONE_FILES — \
                     add it to build.rs or the standalone launch dies at that line"
                );
            }
        }
    }

    /// Mode B round trip: assets → tar.gz → extract-safely → same tree.
    #[test]
    fn bundle_round_trips() {
        if STANDALONE_ASSETS.is_empty() {
            eprintln!("crate-only build (no repo tree) — bundle round-trip skipped");
            return;
        }
        let base = std::env::temp_dir().join(format!("noo-bundle-rt-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        let stage = base.join("stage");
        write_assets(&stage).unwrap();
        let tgz = base.join("b.tar.gz");
        assert!(std::process::Command::new("tar")
            .arg("-czf").arg(&tgz).arg("-C").arg(&stage).arg(".")
            .status().unwrap().success());
        let home = base.join("home");
        std::fs::create_dir_all(&home).unwrap();
        extract_bundle_safely(&std::fs::read(&tgz).unwrap(), &home).unwrap();
        assert!(home.join("docker-compose.cluster.yml").is_file());
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(home.join("scripts/noomesh-start.sh"))
                .unwrap().permissions().mode();
            assert!(mode & 0o111 != 0, "tar must preserve the exec bit: {mode:o}");
        }
        let _ = std::fs::remove_dir_all(&base);
    }

    /// A traversal entry (`../x`) must be refused BEFORE extraction.
    #[test]
    fn bundle_rejects_path_traversal() {
        let base = std::env::temp_dir().join(format!("noo-bundle-evil-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        // Built in-process, byte for byte. The evil archive used to come from
        // the host's `tar --transform 's|x|../escaped|'`, and GNU tar strips a
        // leading `../` from member names when it WRITES an archive — so on a
        // CI runner (host7, 2026-09-28) the "evil" archive held a harmless
        // `escaped`, extraction rightly succeeded, and the test failed with the
        // extractor doing nothing wrong. Its guard only asked whether
        // --transform existed, not whether the trick had worked.
        let tgz = base.join("evil.tgz");
        std::fs::write(&tgz, evil_tar_gz("../escaped", b"pwned")).unwrap();
        // The precondition, checked with the same tool the extractor uses: if
        // this host's tar does not SEE a `..` entry, the test proves nothing.
        let listed = std::process::Command::new("tar").arg("-tzf").arg(&tgz).output().unwrap();
        let listed = String::from_utf8_lossy(&listed.stdout);
        assert!(listed.lines().any(|l| l.trim() == "../escaped"),
            "the test archive must list a `..` entry to test anything, got: {listed:?}");
        let home = base.join("home");
        std::fs::create_dir_all(&home).unwrap();
        let err = extract_bundle_safely(&std::fs::read(&tgz).unwrap(), &home).unwrap_err();
        assert!(err.contains("escapes"), "unexpected error: {err}");
        assert!(!base.join("escaped").exists(), "traversal file was written!");
        let _ = std::fs::remove_dir_all(&base);
    }

    /// A one-entry `.tar.gz` whose member name is written verbatim — nothing
    /// normalises it on the way in, which is the point. ustar header, the
    /// data padded to 512, two zero blocks; gzip with stored (uncompressed)
    /// deflate blocks and a real CRC32, so any gzip reader accepts it.
    fn evil_tar_gz(name: &str, data: &[u8]) -> Vec<u8> {
        let mut h = [0u8; 512];
        h[..name.len()].copy_from_slice(name.as_bytes());
        h[100..108].copy_from_slice(b"0000644\0");
        h[108..116].copy_from_slice(b"0000000\0");
        h[116..124].copy_from_slice(b"0000000\0");
        h[124..136].copy_from_slice(format!("{:011o}\0", data.len()).as_bytes());
        h[136..148].copy_from_slice(b"00000000000\0");
        h[148..156].copy_from_slice(b"        ");
        h[156] = b'0';
        h[257..263].copy_from_slice(b"ustar\0");
        h[263..265].copy_from_slice(b"00");
        let sum: u32 = h.iter().map(|&b| b as u32).sum();
        h[148..156].copy_from_slice(format!("{sum:06o}\0 ").as_bytes());
        let mut tar = h.to_vec();
        tar.extend_from_slice(data);
        tar.resize(tar.len().div_ceil(512) * 512, 0);
        tar.resize(tar.len() + 1024, 0);

        let mut crc = !0u32;
        for &b in &tar {
            crc ^= b as u32;
            for _ in 0..8 {
                crc = if crc & 1 == 1 { (crc >> 1) ^ 0xEDB8_8320 } else { crc >> 1 };
            }
        }
        let mut gz = vec![0x1f, 0x8b, 8, 0, 0, 0, 0, 0, 0, 0xff];
        let chunks: Vec<&[u8]> = tar.chunks(65_535).collect();
        for (i, c) in chunks.iter().enumerate() {
            gz.push(u8::from(i + 1 == chunks.len())); // BFINAL on the last, BTYPE=00 (stored)
            let len = c.len() as u16;
            gz.extend_from_slice(&len.to_le_bytes());
            gz.extend_from_slice(&(!len).to_le_bytes());
            gz.extend_from_slice(c);
        }
        gz.extend_from_slice(&(!crc).to_le_bytes());
        gz.extend_from_slice(&(tar.len() as u32).to_le_bytes());
        gz
    }

    // ── retiring a file a past release shipped ──────────

    fn fresh_home(tag: &str) -> PathBuf {
        let home = std::env::temp_dir().join(format!("noo-retire-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&home);
        std::fs::create_dir_all(&home).unwrap();
        home
    }

    fn read_manifest_files(home: &Path) -> std::collections::BTreeMap<String, Option<String>> {
        let text = std::fs::read_to_string(home.join(MATERIALISED_MANIFEST)).unwrap();
        let m: Manifest = serde_json::from_str(&text).unwrap();
        assert_eq!(m.version, MANIFEST_VERSION);
        m.files
    }

    #[test]
    fn first_materialise_with_no_manifest_writes_one_and_removes_nothing() {
        let home = fresh_home("first");
        let assets: &[(&str, &[u8], bool)] = &[("a.txt", b"AAA", false), ("dir/b.txt", b"BBB", false)];
        write_assets_for_test(&home, assets, &[]);
        let report = finish_materialize(&home, assets, &[], &[], "1.0.0");
        assert!(report.retired.is_empty());
        assert!(report.moved_aside.is_empty());
        let files = read_manifest_files(&home);
        assert_eq!(files.get("a.txt"), Some(&Some(sha256_hex(b"AAA"))));
        assert_eq!(files.get("dir/b.txt"), Some(&Some(sha256_hex(b"BBB"))));
        assert!(home.join("a.txt").is_file());
        let _ = std::fs::remove_dir_all(&home);
    }

    /// A helper mirroring `write_assets` but over an injectable table, for
    /// tests that must not depend on the real embedded STANDALONE_ASSETS.
    fn write_assets_for_test(home: &Path, assets: &[(&str, &[u8], bool)], rendered_once: &[&str]) {
        for (rel, bytes, _exec) in assets {
            let dest = home.join(rel);
            if let Some(parent) = dest.parent() {
                std::fs::create_dir_all(parent).unwrap();
            }
            if rendered_once.contains(rel) && dest.is_file() {
                continue;
            }
            std::fs::write(&dest, bytes).unwrap();
        }
    }

    #[test]
    fn old_manifest_path_dropped_from_current_set_is_removed_when_unmodified() {
        let home = fresh_home("removed");
        let old_assets: &[(&str, &[u8], bool)] = &[("keep.txt", b"K", false), ("gone.txt", b"GONE", false)];
        write_assets_for_test(&home, old_assets, &[]);
        finish_materialize(&home, old_assets, &[], &[], "1.0.0");
        assert!(home.join("gone.txt").is_file());

        // New release no longer ships gone.txt.
        let new_assets: &[(&str, &[u8], bool)] = &[("keep.txt", b"K", false)];
        write_assets_for_test(&home, new_assets, &[]);
        let report = finish_materialize(&home, new_assets, &[], &[], "1.0.1");
        assert!(!home.join("gone.txt").exists(), "unmodified retired file must be removed");
        assert!(report.retired.iter().any(|l| l.contains("gone.txt")));
        assert!(home.join("keep.txt").is_file());
        let _ = std::fs::remove_dir_all(&home);
    }

    #[test]
    fn old_manifest_path_edited_locally_is_moved_aside() {
        let home = fresh_home("moved");
        let old_assets: &[(&str, &[u8], bool)] = &[("gone.txt", b"GONE", false)];
        write_assets_for_test(&home, old_assets, &[]);
        finish_materialize(&home, old_assets, &[], &[], "1.0.0");
        // Operator edited it after materialise.
        std::fs::write(home.join("gone.txt"), b"EDITED BY OPERATOR").unwrap();

        let new_assets: &[(&str, &[u8], bool)] = &[];
        let report = finish_materialize(&home, new_assets, &[], &[], "1.0.1");
        assert!(!home.join("gone.txt").exists());
        let aside = home.join("gone.txt.retired-1.0.1");
        assert!(aside.is_file(), "expected {}", aside.display());
        assert_eq!(std::fs::read(&aside).unwrap(), b"EDITED BY OPERATOR");
        assert!(report.moved_aside.iter().any(|l| l.contains("gone.txt") && l.contains("gone.txt.retired-1.0.1")));
        let _ = std::fs::remove_dir_all(&home);
    }

