        finish_materialize(&home, old_assets, &[], &[], "0.6.5");
        // The release that no longer embeds it removes the unmodified file.
        let report = finish_materialize(&home, &[], &[], &[], "0.6.6");
        assert!(!home.join(name).exists(), "the leftover overlay was kept");
