    #[test]
    fn manifest_traversal_and_absolute_and_symlink_escape_paths_are_refused() {
        let home = fresh_home("evil-manifest");
        // A sentinel OUTSIDE home that a hostile manifest tries to reach.
        let outside_dir = std::env::temp_dir().join(format!("noo-retire-outside-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&outside_dir);
        std::fs::create_dir_all(&outside_dir).unwrap();
        let sentinel = outside_dir.join("sentinel.txt");
        std::fs::write(&sentinel, b"do not touch").unwrap();

        // A symlinked directory inside home pointing OUTSIDE home.
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(&outside_dir, home.join("escape-link")).unwrap();
        }

        let mut files = std::collections::BTreeMap::new();
        files.insert("../evil.txt".to_string(), Some("deadbeef".repeat(8)));
        files.insert("/etc/evil.txt".to_string(), Some("deadbeef".repeat(8)));
        #[cfg(unix)]
        files.insert("escape-link/sentinel.txt".to_string(), Some(sha256_hex(b"do not touch")));
        let manifest = Manifest { version: MANIFEST_VERSION, cli: "1.0.0".into(), files };
        write_manifest_atomic(&home, &manifest).unwrap();

        let report = finish_materialize(&home, &[], &[], &[], "1.0.1");
        assert!(sentinel.is_file(), "a path outside home must never be touched");
        assert_eq!(std::fs::read(&sentinel).unwrap(), b"do not touch");
        assert!(!home.join("../evil.txt").exists());
        assert!(report.retired.is_empty());
        assert!(report.moved_aside.is_empty());
        assert!(!report.skipped.is_empty(), "the unsafe paths must at least be noted");
        let _ = std::fs::remove_dir_all(&home);
        let _ = std::fs::remove_dir_all(&outside_dir);
    }

    #[test]
    fn corrupt_manifest_is_treated_as_absent_and_a_fresh_one_is_written() {
        let home = fresh_home("corrupt");
        std::fs::write(home.join(MATERIALISED_MANIFEST), b"not json at all").unwrap();
        let assets: &[(&str, &[u8], bool)] = &[("a.txt", b"AAA", false)];
        write_assets_for_test(&home, assets, &[]);
        let report = finish_materialize(&home, assets, &[], &[], "1.0.0");
        assert!(report.retired.is_empty());
        assert!(report.moved_aside.is_empty());
        assert!(report.skipped.iter().any(|l| l.contains(MATERIALISED_MANIFEST)));
        let files = read_manifest_files(&home);
        assert_eq!(files.get("a.txt"), Some(&Some(sha256_hex(b"AAA"))));
        let _ = std::fs::remove_dir_all(&home);
    }

    #[test]
    fn write_assets_alone_never_removes_anything_or_writes_a_manifest() {
        if STANDALONE_ASSETS.is_empty() {
            eprintln!("crate-only build (no repo tree) — skipped");
            return;
        }
        let home = fresh_home("bundle-export");
        write_assets(&home).unwrap();
        assert!(!home.join(MATERIALISED_MANIFEST).exists(),
            "write_assets (the bundle-export path) must never write the retire manifest");
        // A stray extra file must survive write_assets alone.
        std::fs::write(home.join("operator-extra.txt"), b"mine").unwrap();
        write_assets(&home).unwrap();
        assert!(home.join("operator-extra.txt").is_file());
        let _ = std::fs::remove_dir_all(&home);
    }

    #[test]
    fn manifest_is_written_only_after_every_asset_write_succeeds() {
        let home = fresh_home("partial-write");
        // Seed an OLD manifest so we can tell whether a NEW one replaced it.
        let mut old_files = std::collections::BTreeMap::new();
        old_files.insert("ok.txt".to_string(), Some(sha256_hex(b"whatever")));
        write_manifest_atomic(&home, &Manifest {
            version: MANIFEST_VERSION, cli: "0.9.0".into(), files: old_files,
        }).unwrap();

        // Make "blocked" an existing DIRECTORY so writing a file there fails.
        std::fs::create_dir_all(home.join("blocked")).unwrap();
        let assets: &[(&str, &[u8], bool)] = &[("ok.txt", b"FINE", false), ("blocked", b"X", false)];
        let err = write_assets_for_test_fallible(&home, assets, &[]);
        assert!(err.is_err(), "writing a file where a directory sits must fail");

        let m: Manifest = serde_json::from_str(
            &std::fs::read_to_string(home.join(MATERIALISED_MANIFEST)).unwrap()).unwrap();
        assert_eq!(m.cli, "0.9.0", "the manifest must be the OLD one — finish_materialize never ran");
        let _ = std::fs::remove_dir_all(&home);
    }

    fn write_assets_for_test_fallible(home: &Path, assets: &[(&str, &[u8], bool)], rendered_once: &[&str]) -> io::Result<()> {
        for (rel, bytes, _exec) in assets {
            let dest = home.join(rel);
            if let Some(parent) = dest.parent() {
                std::fs::create_dir_all(parent)?;
            }
            if rendered_once.contains(rel) && dest.is_file() {
                continue;
            }
            std::fs::write(&dest, bytes)?;
        }
        Ok(())
    }

    #[test]
    fn known_retired_paths_are_not_currently_embedded() {
        if STANDALONE_ASSETS.is_empty() {
            eprintln!("crate-only build (no repo tree) — skipped");
            return;
        }
        let embedded: std::collections::HashSet<&str> =
            STANDALONE_ASSETS.iter().map(|(d, _, _)| *d).collect();
        for (path, _) in KNOWN_RETIRED {
            assert!(!embedded.contains(path),
                "{path} is in KNOWN_RETIRED but is ALSO currently embedded — a file un-retired \
                 later must be removed from KNOWN_RETIRED, or a fresh install of it would be \
                 deleted on the very next materialise");
        }
    }

    #[test]
    fn the_retired_scripts_seen_on_host8_are_listed() {
        for p in ["scripts/noo-cluster-executor.sh", "scripts/noo-host-watcher.service",
                  "scripts/noo-host-watcher.sh", "scripts/restart-watchdog.sh"] {
            let (_, shas) = KNOWN_RETIRED.iter().find(|(q, _)| *q == p)
                .unwrap_or_else(|| panic!("{p} missing from KNOWN_RETIRED"));
            assert!(!shas.is_empty(), "{p} has no shipped shas");
            assert!(shas.iter().all(|h| h.len() == 64 && !h.starts_with("e3b0c442")),
                "{p}: malformed sha (or the empty-file sha of a deletion commit)");
        }
    }

    #[test]
    fn known_retired_never_reaches_outside_the_install_root() {
        let home = fresh_home("kr-escape");
        let outside = std::env::temp_dir().join(format!("noo-kr-outside-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&outside);
        std::fs::create_dir_all(&outside).unwrap();
        // Stands in for a unit installed into /etc/systemd or ~/.config/systemd.
        std::fs::write(outside.join("noo-host-watcher.service"), b"INSTALLED UNIT").unwrap();
        let unit_sha = sha256_hex(b"INSTALLED UNIT");
        #[cfg(unix)]
        std::os::unix::fs::symlink(&outside, home.join("scripts")).unwrap();
        let abs = outside.join("noo-host-watcher.service").display().to_string();
        let known: &[(&str, &[&str])] = &[
            ("scripts/noo-host-watcher.service", &[&unit_sha]), // via symlinked parent
            ("../noo-host-watcher.service", &[&unit_sha]),       // via ..
            (&abs, &[&unit_sha]),                                 // absolute
        ];
        let report = finish_materialize(&home, &[], &[], known, "1.0.0");
        assert_eq!(std::fs::read(outside.join("noo-host-watcher.service")).unwrap(), b"INSTALLED UNIT");
        assert!(report.retired.is_empty() && report.moved_aside.is_empty());
        let _ = std::fs::remove_dir_all(&home);
        let _ = std::fs::remove_dir_all(&outside);
    }

    #[test]
    fn known_retired_moves_an_edited_leftover_aside_under_the_root() {
        let home = fresh_home("kr-leftover");
        std::fs::create_dir_all(home.join("scripts")).unwrap();
        std::fs::write(home.join("scripts/noo-host-watcher.sh"), b"EDITED").unwrap();
        let report = finish_materialize(&home, &[], &[], KNOWN_RETIRED, "1.0.0");
        assert!(!home.join("scripts/noo-host-watcher.sh").exists());
        assert!(home.join("scripts/noo-host-watcher.sh.retired-1.0.0").is_file());
        assert!(!report.moved_aside.is_empty());
        let _ = std::fs::remove_dir_all(&home);
    }
